import{_ as i,o as t,c as l,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"2019-04-25 :: Ceph Performance meeting","description":"","frontmatter":{"title":"2019-04-25 :: Ceph Performance meeting","date":"2019-04-25T00:00:00.000Z","updated":"2019-04-26T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","Pull Request","RocksDB"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-04-25_-_-_Ceph_Performance_meeting.md","filePath":"posts/2019/2019-04-25_-_-_Ceph_Performance_meeting.md","lastUpdated":1780459816000}'),o={name:"posts/2019/2019-04-25_-_-_Ceph_Performance_meeting.md"};function r(s,e,n,p,_,g){return t(),l("div",null,[...e[0]||(e[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年4月25日</p><p><strong>参会人员</strong>： Igor, Adam, Radek, Ma Jinping, Sam, Daehan, Abhishek, Nick等</p><p><strong>会议主题</strong>： Ceph分布式存储项目进展及性能讨论</p><p><strong>关键细节与议题</strong>：</p><ul><li><strong>Pull Requests (PRs) 讨论</strong>： <ul><li>本周有许多PR被关闭，部分原因是旧的BOTS自动关闭了这些PR。</li><li>Igor的PR涉及RocksDB的预取和缓冲读取模式，正在调查直接IO模式。</li><li>Ma Jinping的PR进行了一些性能优化，但具体影响尚不明确。</li><li>Radek的PR引入了Crimson OSD的执行阶段，目前还在讨论中。</li><li>Sam的PR关于增强指令缓存局部性，目前还在讨论中。</li><li>Adam的PR关于优化Booster缓存和Roxy D块缓存，已合并。</li><li>Beige的PR关于UTF-8优化，已合并。</li><li>Jason的PR关于RBE和右回退哈希，目前还在讨论中。</li><li>Daehan的PR关于测试RocksDB分配器，希望将其转换为单元测试。</li><li>Sage希望保留Adam关于Blue Store分配器的测试工作。</li></ul></li><li><strong>其他讨论</strong>： <ul><li>Adam正在研究TeaDB，并发现其写放大率较低。</li><li>Nick询问了关于RocksDB的问题，希望将其集成到Ceph中。</li><li>Abhishek和Nick讨论了使用S3的App性能问题，发现PR276997会影响性能。</li></ul></li><li><strong>后续行动计划</strong>： <ul><li>继续对现有的PR进行审查和合并。</li><li>探索将TeaDB集成到Ceph中的可能性。</li><li>优化S3相关的性能问题。</li></ul></li></ul><p><strong>总结</strong>：</p><p>本周Ceph项目的进展顺利，多个PR已合并，但仍有一些PR需要进一步讨论和优化。团队成员将继续努力，确保Ceph项目的稳定性和性能。</p>',8)])])}const P=i(o,[["render",r]]);export{m as __pageData,P as default};
